const attempts = new Map();
export function rateLimit(key, limit = 10, windowMs = 15 * 60 * 1000) {
  const now = Date.now();
  const record = attempts.get(key) || { count: 0, resetAt: now + windowMs };
  if (now >= record.resetAt) { record.count = 0; record.resetAt = now + windowMs; }
  record.count += 1;
  attempts.set(key, record);
  return { allowed: record.count <= limit, retryAfter: Math.ceil((record.resetAt - now) / 1000) };
}
